void process_sanitized_command(int socket_fd)
{
    char cmd[128] = "";
    int bytes = recv(socket_fd, cmd, sizeof(cmd) - 1, 0);
    if (bytes > 0) {
        cmd[bytes] = '\0';
        /* SANITIZATION DEFENSE: Strict validation blocks injection */
        if (is_valid_alphanumeric_safe(cmd)) {
            execl("/bin/ls", "ls", cmd, NULL);
        }
    }
}
